#include "workbenchwidget.h"
#include "netclient.h"
#include "protocol.h"
#include <QtWidgets>

namespace {
class Heatmap : public QWidget {
public: explicit Heatmap(QWidget *p=nullptr):QWidget(p){setMinimumHeight(180);}
    void setValues(const QVector<int>&v){m=v;update();}
protected: void paintEvent(QPaintEvent*)override{QPainter p(this);p.setRenderHint(QPainter::Antialiasing);if(m.isEmpty()){p.setPen("#7D867F");p.drawText(rect(),Qt::AlignCenter,"近 7 日暂无订单活跃数据");return;}int max=1;for(int x:m)max=qMax(max,x);const int l=34,t=18,cols=12,rows=7;double cw=(width()-l-8.0)/cols,ch=(height()-t-20.0)/rows;for(int r=0;r<rows;r++){p.setPen("#89918A");p.drawText(0,t+r*ch,l-5,ch,Qt::AlignRight|Qt::AlignVCenter,QString::number(r*2));for(int c=0;c<cols;c++){int x=m.value(r*cols+c),a=x?55+qRound(170.0*x/max):18;p.setPen(Qt::NoPen);p.setBrush(QColor(64,145,91,a));p.drawRoundedRect(QRectF(l+c*cw+2,t+r*ch+2,cw-5,ch-5),4,4);}}}
private:QVector<int>m;
};
QFrame* panel(const QString&t,QWidget*p,QVBoxLayout**body){auto*f=new QFrame(p);f->setObjectName("workbenchPanel");auto*l=new QVBoxLayout(f);l->setContentsMargins(18,15,18,15);l->setSpacing(8);auto*h=new QLabel(t,f);h->setObjectName("workbenchPanelTitle");l->addWidget(h);*body=l;return f;}
QLabel* label(const QString&t,const QString&n,QWidget*p){auto*x=new QLabel(t,p);x->setObjectName(n);return x;}
QString greeting(){const int hour=QTime::currentTime().hour();if(hour<6)return QStringLiteral("夜深了，管理员");if(hour<12)return QStringLiteral("早上好，管理员");if(hour<18)return QStringLiteral("下午好，管理员");return QStringLiteral("晚上好，管理员");}
}

WorkbenchWidget::WorkbenchWidget(NetClient*netClient,QWidget*p):QWidget(p),m_net(netClient){
 setObjectName("workbenchPage");auto*r=new QVBoxLayout(this);r->setContentsMargins(26,18,26,24);r->setSpacing(14);
 r->addWidget(label(greeting(),"workbenchGreeting",this));r->addWidget(label("当前充电设施与运营状态概览","workbenchSubtitle",this));
 auto*c=new QHBoxLayout;c->setSpacing(14);QStringList ts={"充电中设备","闲置设备","故障设备","进行中订单"},tones={"mint","sand","peach","lavender"};
 for(int i=0;i<4;i++){auto*b=new QPushButton(this);b->setObjectName("workbenchMetric");b->setProperty("tone",tones[i]);b->setMinimumHeight(116);b->setCursor(Qt::PointingHandCursor);auto*l=new QVBoxLayout(b);l->setContentsMargins(18,14,18,14);l->setSpacing(4);l->addWidget(label(ts[i],"workbenchMetricTitle",b));m_cards[i]=label("--","workbenchMetricValue",b);m_cardNotes[i]=label("等待数据…","workbenchMetricNote",b);l->addWidget(m_cards[i]);l->addWidget(m_cardNotes[i]);c->addWidget(b);if(i<3)connect(b,&QPushButton::clicked,this,[this,i]{emit openRealtime(QStringList{"busy","idle","fault"}[i]);});else connect(b,&QPushButton::clicked,this,[this]{emit openOrders("charging");});}r->addLayout(c);
 auto*g=new QGridLayout;g->setSpacing(14);g->setColumnStretch(0,3);g->setColumnStretch(1,2);QVBoxLayout*body=nullptr;
 auto*h=panel("充电活跃热力图",this,&body);body->addWidget(label("基于现有进行中订单数据统计（小时分布）","workbenchPanelHint",h));m_heatmap=new Heatmap(h);body->addWidget(m_heatmap,1);g->addWidget(h,0,0);
 auto*a=panel("今日关注",this,&body);m_attentionText=label("●  故障设备                         0\n○  冻结用户                         --\n○  进行中订单                     0","workbenchList",a);body->addWidget(m_attentionText,1);g->addWidget(a,0,1);
 auto*s=panel("电站实时运营排行",this,&body);m_rankingText=label("暂无可视化统计数据","workbenchList",s);m_rankingText->setWordWrap(true);body->addWidget(m_rankingText,1);g->addWidget(s,1,0);
 auto*d=panel("最近业务动态",this,&body);m_activityText=label("暂无最新业务动态","workbenchList",d);m_activityText->setWordWrap(true);body->addWidget(m_activityText,1);g->addWidget(d,1,1);
 auto*noticePanel=panel("运营提示 / 系统状态",this,&body);m_noticeText=label("● 后端连接状态将根据实时通信更新","workbenchList",noticePanel);m_noticeText->setWordWrap(true);body->addWidget(m_noticeText);g->addWidget(noticePanel,2,0,1,2);r->addLayout(g,1);load();
}

void WorkbenchWidget::load(){if(!m_net)return;auto pr=m_net->request(Protocol::makeRequest(Protocol::MsgType::AdminPileList));auto data=pr.value("data").toObject(),st=data.value("stats").toObject();int busy=st.value("busy").toObject().value("count").toInt(),idle=st.value("idle").toObject().value("count").toInt(),fault=st.value("fault").toObject().value("count").toInt(),total=busy+idle+fault;auto piles=data.value("list").toArray();QMap<QString,QPair<int,int>> stations;for(auto v:piles){auto o=v.toObject();auto&x=stations[o.value("station").toString()];x.second++;if(o.value("status").toString()=="busy")x.first++;}m_cards[0]->setText(QString::number(busy));m_cards[1]->setText(QString::number(idle));m_cards[2]->setText(QString::number(fault));m_cardNotes[0]->setText(total?QString("占设备总数 %1%").arg(busy*100.0/total,0,'f',1):"占设备总数 --");m_cardNotes[1]->setText(total?QString("占设备总数 %1%").arg(idle*100.0/total,0,'f',1):"占设备总数 --");m_cardNotes[2]->setText(fault?"需要重点关注":"当前运行正常");auto orr=m_net->request(Protocol::makeRequest(Protocol::MsgType::AdminOrderList,QJsonObject{{"status","charging"},{"page",1},{"page_size",20}}));auto od=orr.value("data").toObject();auto activeOrders=od.value("total").toInt();auto recentQuery=QJsonObject{{"page",1},{"page_size",20},{"start_time",QDateTime::currentDateTime().addDays(-7).toString(Qt::ISODate)},{"end_time",QDateTime::currentDateTime().toString(Qt::ISODate)}};auto recentResponse=m_net->request(Protocol::makeRequest(Protocol::MsgType::AdminOrderList,recentQuery));auto recentData=recentResponse.value("data").toObject();auto list=recentData.value("list").toArray();int active=activeOrders;auto users=m_net->request(Protocol::makeRequest(Protocol::MsgType::AdminUserList)).value("data").toObject().value("list").toArray();int frozen=0;for(auto value:users)if(value.toObject().value("status").toString()=="frozen")++frozen;m_cards[3]->setText(QString::number(active));m_cardNotes[3]->setText(active?"正在处理":"当前暂无进行中订单");m_attentionText->setText(QString("●  故障设备                         %1\n○  冻结用户                         %2\n○  进行中订单                     %3").arg(fault).arg(frozen).arg(active));QString rank;for(auto i=stations.cbegin();i!=stations.cend();++i)if(!i.key().isEmpty())rank+=QString("%1\n利用率 %2%（%3 / %4）\n\n").arg(i.key()).arg(i.value().second?i.value().first*100.0/i.value().second:0,0,'f',1).arg(i.value().first).arg(i.value().second);m_rankingText->setText(rank.isEmpty()?"暂无可视化统计数据":rank);QString activity;QVector<int>heat(84);for(auto v:list){auto o=v.toObject();auto dt=QDateTime::fromString(o.value("start_time").toString(),Qt::ISODate);if(dt.isValid())heat[(dt.date().dayOfWeek()-1)*12+qBound(0,dt.time().hour()/2,11)]++;activity+=QString("%1  %2\n%3 · %4\n%5\n\n").arg(o.value("order_no").toString(),o.value("status").toString(),o.value("station_name").toString(),o.value("pile_code").toString(),o.value("start_time").toString());}static_cast<Heatmap*>(m_heatmap)->setValues(heat);m_activityText->setText(activity.isEmpty()?"暂无最新业务动态":activity.left(500));m_noticeText->setText(QString("● 当前后端连接正常\n● 当前有 %1 台设备正在充电\n● 当前故障设备 %2 台").arg(busy).arg(fault));}
